// Consulta híbrida en Neo4j: nodos semilla por vector + expansión 2 saltos
CALL db.index.vector.queryNodes('entity_idx', 5, $query_embedding) YIELD node, score
MATCH path = (node)-[r:DEPENDS_ON|CAUSES*1..2]-(relacionado)
RETURN node.name, [rel IN relationships(path) | type(rel)], relacionado.name LIMIT 25;

Human-in-the-loop.ejemplo:
# Pausa declarativa en LangGraph antes de ejecutar un pago
from langgraph.types import interrupt

def aprobar_pago(state):
    decision = interrupt({"accion": "transferencia", "importe": state["monto"]})
    if not decision.get("aprobado"):
        return {"estado": "cancelado"}
    return {"estado": "autorizado"}

LangSmith.ejemplo:
from langsmith import traceable
from openai import OpenAI
from langsmith.wrappers import wrap_openai

client = wrap_openai(OpenAI())

@traceable(name="pipeline_rag")
def responder(pregunta: str):
    return client.chat.completions.create(model="gpt-4o-mini", messages=[{"role": "user", "content": pregunta}])

